#!/usr/bin/env bash
# Agent PRs carry no "Generated by/with Claude" line, session link or co-author trailer in the
# body (CLAUDE.md, Git and attribution). The prompt asks for that; this makes it true regardless.
# Usage: strip-pr-attribution.sh [minutes]   (PRs opened in the last N minutes, default 60)
set -euo pipefail
since=$(date -u -d "-${1:-60} minutes" +%Y-%m-%dT%H:%M:%SZ)
for n in $(gh pr list --state open --search "created:>=$since" --json number --jq '.[].number'); do
  body=$(gh pr view "$n" --json body --jq .body)
  clean=$(printf '%s\n' "$body" | python3 -c '
import re, sys
lines = sys.stdin.read().split("\n")
bad = re.compile(r"generated (by|with) \[?claude|claude\.ai/code/session|claude\.com/claude-code|^co-authored-by:.*(claude|anthropic)|^claude-session:", re.I)
kept = [l for l in lines if not bad.search(l)]
text = "\n".join(kept).rstrip()
text = re.sub(r"\n+(---|\*\*\*|___)\s*$", "", text).rstrip()   # a rule left dangling above the removed line
print(text)')
  if [ "$body" != "$clean" ]; then
    gh pr edit "$n" --body "$clean" >/dev/null && echo "stripped attribution from #$n"
  fi
done
